class WeightedLoadBalancer {
  constructor(nodes) {
    // nodes: [{ name, weight }]，weight 必须为正整数
    this.nodes = nodes.map((n) => ({ name: n.name, weight: n.weight, currentWeight: 0 }));
    this.totalWeight = nodes.reduce((s, n) => s + n.weight, 0);
  }

  pick() {
    // ① 每个节点当前权重 += 静态权重
    for (const node of this.nodes) node.currentWeight += node.weight;
    // ② 选 currentWeight 最大者（并列取第一个，保证确定性）
    let best = this.nodes[0];
    for (const node of this.nodes) {
      if (node.currentWeight > best.currentWeight) best = node;
    }
    // ③ 被选中节点 currentWeight -= 总权重
    best.currentWeight -= this.totalWeight;
    return best.name;
  }
}

// 测试：权重 A:B:C = 5:1:1，一个周期 7 次
const lb = new WeightedLoadBalancer([
  { name: 'A', weight: 5 },
  { name: 'B', weight: 1 },
  { name: 'C', weight: 1 }
]);
const seq = Array.from({ length: 14 }, () => lb.pick());
console.log('连续 14 次（两个周期）:', seq.join(' '));
const count = {};
for (const n of seq) count[n] = (count[n] || 0) + 1;
console.log('计数（A:B:C 应≈10:2:2）:', count);
