// 对照：等权 1:1:1 时序列在三节点间均匀轮转，天然无连续
const lb3 = new WeightedLoadBalancer([
  { name: 'A', weight: 1 }, { name: 'B', weight: 1 }, { name: 'C', weight: 1 }
]);
const even = Array.from({ length: 9 }, () => lb3.pick());
console.log('等权 1:1:1 序列:', even.join(' '));
const noConsecutive = even.every((n, i) => i === 0 || n !== even[i - 1]);
const evenCount = {};
for (const n of even) evenCount[n] = (evenCount[n] || 0) + 1;
console.log('等权无连续命中:', noConsecutive, ' 计数:', evenCount); // true，各 3 次
// 跨周期不变量：任意 totalWeight 的整数倍长度内，各节点被选次数严格按权重分配
const lb4 = new WeightedLoadBalancer([
  { name: 'A', weight: 5 }, { name: 'B', weight: 1 }, { name: 'C', weight: 1 }
]);
const twoCycles = Array.from({ length: 14 }, () => lb4.pick());
const tc = {};
for (const n of twoCycles) tc[n] = (tc[n] || 0) + 1;
console.log('两个周期(14次)计数（严格 10:2:2）:', tc);
